affix-template-setup.code:
# --- PARAMS ---
POS_NAME = "Nome"  # POS (or subcategory) name in the analysis writing system, compared NFC
TEMPLATE_NAME = "zzRecipeTestTemplate"  # template name; a live run creates it on the POS when missing
SLOT_NAMES = []  # existing slot names to ensure on the template; each must already be owned by the POS, empty means validate-only
EXEMPLAR_HEADWORD = "cibubu"  # exemplar entry whose stem MSAs are repointed to the POS, keeping inflection class
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


SIDES = ("prefix", "suffix", "proclitic", "enclitic")


def template_slots(template):
    return {
        "prefix": list(template.prefix_slots),
        "suffix": list(template.suffix_slots),
        "proclitic": list(template.proclitic_slots),
        "enclitic": list(template.enclitic_slots),
    }


def describe_template(template):
    bits = []
    filled = 0
    for side in SIDES:
        slots = template_slots(template)[side]
        names = [s.name + ("?" if s.optional else "") for s in slots]
        if names:
            bits.append(f"{side}={names}")
        filled += sum(1 for s in slots for _a in s.affixes)
    body = "; ".join(bits) if bits else "(no slots)"
    return f"template '{template.name}': {body} [{filled} affix(es) in slots]"


def find_template(pos, name):
    for cand in project.MorphRules.GetAllAffixTemplatesForPOS(pos):
        if nfc(cand.name) == nfc(name):
            return cand
    return None


ok = True
pos = None
ex_entry = None

# 1. Resolve the POS (GetAll is recursive, so subcategories match too).
matches = [p for p in project.POS.GetAll() if nfc(project.POS.GetName(p)) == nfc(POS_NAME)]
if len(matches) != 1:
    report.Error(f"POS {POS_NAME!r}: found {len(matches)} matches, need exactly 1")
    ok = False
else:
    pos = matches[0]
    pos_name = project.POS.GetName(pos)
    parent = project.POS.GetParent(pos)
    if parent is None:
        report.Info(f"POS '{pos_name}': top-level category")
    else:
        report.Info(f"POS '{pos_name}': subcategory of '{project.POS.GetName(parent)}'")
    subs = sorted(project.POS.GetName(s) for s in project.POS.GetSubcategories(pos))
    if subs:
        report.Info(f"POS '{pos_name}': subcategories {subs}")

# 2. Resolve the exemplar entry by exact headword (NFC both sides).
if ok:
    cands = [e for e in project.LexEntry.GetAll() if nfc(project.LexEntry.GetHeadword(e)) == nfc(EXEMPLAR_HEADWORD)]
    if len(cands) != 1:
        report.Error(f"exemplar {EXEMPLAR_HEADWORD!r}: found {len(cands)} entries, need exactly 1")
        ok = False
    else:
        ex_entry = cands[0]

# 3. Validate every wanted slot is already owned by the POS (existing slots only).
slot_by_name = {}
if ok:
    for s in project.POS.GetAffixSlots(pos):
        slot_by_name.setdefault(nfc(project.POS.GetSlotName(s)), s)
    for wanted in SLOT_NAMES:
        if nfc(wanted) not in slot_by_name:
            report.Error(f"slot {wanted!r}: not owned by POS '{pos_name}'; this recipe only adds existing slots")
            ok = False

if not ok:
    report.Error("validation failed: fix PARAMS before any write")
else:
    report.Info("BEFORE:")
    report.Info(f"  POS '{pos_name}': owns slots {sorted(slot_by_name)}")
    for t in project.MorphRules.GetAllAffixTemplatesForPOS(pos):
        report.Info(f"  {describe_template(t)}")
    hw = project.LexEntry.GetHeadword(ex_entry)
    senses = project.LexEntry.GetSenses(ex_entry)
    if not senses:
        report.Warning(f"  exemplar '{hw}': entry has no senses; nothing to repoint")
    by_concrete = {m.concrete: m for m in project.MSA.GetAll(ex_entry)}
    stems = []
    for sense in senses:
        gloss = project.Senses.GetGloss(sense)
        raw_msa = project.Senses.GetMSA(sense)
        wrap = by_concrete.get(raw_msa) if raw_msa is not None else None
        if wrap is None or not wrap.is_stem_msa:
            report.Info(f"  exemplar '{hw}' sense '{gloss}': no stem MSA, skipped")
            continue
        cur = project.Senses.GetPartOfSpeechObject(sense)
        cur_name = project.POS.GetName(cur) if cur is not None else None
        report.Info(f"  exemplar '{hw}' sense '{gloss}': stem MSA on POS {cur_name!r}")
        stems.append((sense, gloss, raw_msa, cur, cur_name))

    # 4. Ensure the template exists (create under modifyAllowed only).
    template = find_template(pos, TEMPLATE_NAME)
    if template is None:
        if not modifyAllowed:
            report.Info(f"(dry run) would create template '{TEMPLATE_NAME}' on POS '{pos_name}'")
        if modifyAllowed:
            project.MorphRules.CreateAffixTemplate(pos, TEMPLATE_NAME)
            template = find_template(pos, TEMPLATE_NAME)
            if template is None:
                report.Error(f"created template '{TEMPLATE_NAME}' but cannot find it afterwards")
                ok = False
            else:
                report.Info(f"created template '{template.name}' on POS '{pos_name}'")

    # 5. Ensure each validated slot sits on the template (add under modifyAllowed only).
    if ok and template is not None:
        on_template = {nfc(s.name) for slots in template_slots(template).values() for s in slots}
        side_by_slot = {}
        for t in project.MorphRules.GetAllAffixTemplatesForPOS(pos):
            for side in SIDES:
                for s in template_slots(t)[side]:
                    side_by_slot.setdefault(nfc(s.name), set()).add(side)
        for wanted in SLOT_NAMES:
            slot = slot_by_name[nfc(wanted)]
            slot_label = project.POS.GetSlotName(slot)
            if nfc(wanted) in on_template:
                report.Info(f"slot '{slot_label}': already on template '{template.name}'")
                continue
            sides = side_by_slot.get(nfc(wanted), set())
            if len(sides) != 1:
                report.Error(f"slot '{slot_label}': side unknown or ambiguous {sorted(sides)}; add it by hand")
                continue
            (side,) = sides
            if not modifyAllowed:
                report.Info(f"(dry run) would add slot '{slot_label}' to template '{template.name}' as {side}")
                continue
            if modifyAllowed:
                project.MorphRules.AddSlotToTemplate(template, slot, side)
                on_template.add(nfc(wanted))
                report.Info(f"added slot '{slot_label}' to template '{template.name}' as {side}")

    # 6. Repoint the exemplar stem MSAs, keeping inflection class (flexicon#573).
    repointed = 0
    already = 0
    skipped = 0
    if ok:
        for sense, gloss, raw_msa, cur, cur_name in stems:
            if cur is not None and str(cur.Guid) == str(pos.Guid):
                report.Info(f"sense '{gloss}': already on POS '{pos_name}'; inflection class untouched")
                already += 1
                continue
            saved_icl = project.MSA.GetInflectionClass(raw_msa)
            icl_label = project.InflectionFeatures.InflectionClassGetName(saved_icl) if saved_icl is not None else None
            if not modifyAllowed:
                report.Info(f"(dry run) would repoint sense '{gloss}' from {cur_name!r} to '{pos_name}', keeping inflection class {icl_label} if '{pos_name}' allows it")
                continue
            if modifyAllowed:
                project.MSA.SetStemMsaPos(sense, pos)  # keeps the class when the new POS allows it
                kept = project.MSA.GetInflectionClass(raw_msa)
                if saved_icl is not None and kept is None:
                    report.Warning(f"sense '{gloss}': inflection class {icl_label} does not belong to '{pos_name}' or its parents, so it was cleared")
                report.Info(f"repointed sense '{gloss}': POS {cur_name!r} -> '{pos_name}', inflection class {project.InflectionFeatures.InflectionClassGetName(kept) if kept is not None else None}")
                repointed += 1
        skipped = len(senses) - len(stems)

    if ok:
        report.Info("AFTER:")
        template = find_template(pos, TEMPLATE_NAME)
        if template is None:
            report.Info(f"  template '{TEMPLATE_NAME}': still missing (dry run creates nothing)")
        else:
            report.Info(f"  {describe_template(template)}")
        report.Info(f"  exemplar '{hw}': {repointed} repointed, {already} already correct, {skipped} skipped (no stem MSA)")

affix-templates-and-slots.code:
# --- PARAMS ---
POS_NAMES = ["Verbo"]  # parts of speech whose templates to show (analysis-language names)
SHOW_AFFIXES = True  # list the affixes (with allomorph environments) filling each slot
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


def slot_label(slot):
    return slot.name + ("?" if slot.optional else "")


# inflectional-affix MSA -> "headword env=[...]", built once.
affix_labels = {}
if SHOW_AFFIXES:
    for entry in project.LexEntry.GetAll():
        msas = [m for m in project.MSA.GetAll(entry) if m.is_infl_aff_msa]
        if not msas:
            continue
        envs = sorted(
            set(
                project.Environments.GetStringRepresentation(x)
                for a in project.Allomorphs.GetAll(entry)
                for x in project.Allomorphs.GetPhoneEnv(a)
            )
        )
        label = project.LexEntry.GetHeadword(entry) + (f" env={envs}" if envs else "")
        for msa in msas:
            affix_labels[msa.concrete] = label

wanted = set(nfc(n) for n in POS_NAMES)
seen = set()
for pos in project.POS.GetAll():
    name = nfc(project.POS.GetName(pos))
    if name not in wanted:
        continue
    seen.add(name)
    for template in project.MorphRules.GetAllAffixTemplatesForPOS(pos):
        prefixes = [slot_label(s) for s in template.prefix_slots]
        suffixes = [slot_label(s) for s in template.suffix_slots]
        report.Info(
            f"{name} template '{template.name}'{' (disabled)' if template.disabled else ''}: {prefixes} STEM {suffixes}"
        )
        if SHOW_AFFIXES:
            for slot in list(template.prefix_slots) + list(template.suffix_slots):
                fillers = sorted(affix_labels.get(a, "?") for a in slot.affixes)
                report.Info(f"   {slot_label(slot)}: {fillers}")
for name in sorted(wanted - seen):
    report.Warning(f"no part of speech named {name}")
envs = [project.Environments.GetStringRepresentation(x) for x in project.Environments.GetAll()]
report.Info(f"environments ({len(envs)}): {envs}")

audit-repair-infl-aff-msa-slots.code:
from SIL.LCModel import IMoInflAffMsa

def _slot_label(slot):
    name = slot.Name
    if name is None:
        return "(unnamed)"
    alt = name.BestAnalysisAlternative
    text = alt.Text if alt else ""
    return "" if text == "***" else (text or str(slot.Guid)[:8])

def _infl_slot_report(infl_msa):
    labels = []
    seen = set()
    duplicate = False
    for slot in list(infl_msa.SlotsRC):
        guid = str(slot.Guid).lower()
        if guid in seen:
            duplicate = True
        seen.add(guid)
        labels.append(_slot_label(slot))
    return labels, duplicate

infl_count = 0
malformed = []
for entry in project.LexEntry.GetAll():
    headword = project.LexEntry.GetHeadword(entry)
    for sense in project.LexEntry.GetAllSenses(entry):
        msa = project.Senses.GetGrammaticalInfo(sense)
        if msa is None or getattr(msa, "ClassName", "") != "MoInflAffMsa":
            continue
        infl_count += 1
        infl = IMoInflAffMsa(msa)
        labels, duplicate = _infl_slot_report(infl)
        sense_n = project.Senses.GetSenseNumber(sense)
        flag = " MALFORMED(duplicate slot)" if duplicate else ""
        report.Info(
            f"{headword} sense {sense_n}: infl-aff slots=[{', '.join(labels) or '(none)'}]{flag}"
        )
        if duplicate:
            malformed.append((entry, sense, labels))

report.Info(f"Audited {infl_count} inflectional-affix MSA(s); "
            f"{len(malformed)} with duplicate slot reference(s).")

# Optional repair: set these before a write-enabled run.
REPAIR_HEADWORD = None
REPAIR_SENSE_INDEX = 0
REPAIR_SLOT_NAMES = None  # e.g. ["SubjectConcord", "TAM"]

if REPAIR_HEADWORD and REPAIR_SLOT_NAMES is not None:
    entry = project.LexEntry.Find(REPAIR_HEADWORD)
    if entry is None:
        report.Error(f"Entry {REPAIR_HEADWORD!r} not found")
    else:
        senses = project.LexEntry.GetAllSenses(entry)
        if REPAIR_SENSE_INDEX >= len(senses):
            report.Error(f"Sense index {REPAIR_SENSE_INDEX} out of range")
        else:
            sense = senses[REPAIR_SENSE_INDEX]
            msa = project.Senses.GetGrammaticalInfo(sense)
            if msa is None or getattr(msa, "ClassName", "") != "MoInflAffMsa":
                report.Error("Target sense has no inflectional-affix MSA")
            else:
                pos = project.Senses.GetPartOfSpeechObject(sense)
                slots_by_name = {}
                if pos is not None:
                    for slot in project.POS.GetAffixSlots(pos):
                        slots_by_name[_slot_label(slot)] = slot
                resolved = [slots_by_name[n] for n in REPAIR_SLOT_NAMES if n in slots_by_name]
                missing = [n for n in REPAIR_SLOT_NAMES if n not in slots_by_name]
                if missing:
                    report.Warning(f"Unknown slot name(s) for POS: {missing}")
                if modifyAllowed:
                    project.MSA.SetInflAffMsaSlots(sense, resolved, replace=True)
                    report.Info(
                        f"Replaced SlotsRC on {REPAIR_HEADWORD} sense {REPAIR_SENSE_INDEX} "
                        f"with {len(resolved)} slot(s)"
                    )
                else:
                    report.Info(
                        f"(Would set SlotsRC on {REPAIR_HEADWORD} sense "
                        f"{REPAIR_SENSE_INDEX} to {REPAIR_SLOT_NAMES})"
                    )

