bulk-set-exception-features.code:
# --- PARAMS ---
SELECTION_MODE = "custom_field"  # "custom_field" or "headwords"
CUSTOM_FIELD = "FTFlags"  # name of the custom field to check for "x" marker (ignored if SELECTION_MODE == "headwords")
HEADWORDS = []  # exact headwords to match (ignored if SELECTION_MODE == "custom_field"); empty list = all marked senses
ACTION = "add"  # "add" or "clear"
FEATURE_NAME = ""  # name of exception feature to add; use "" to just clear (ignored if ACTION == "clear")
MORPHTYPE = "all"  # "stem", "deriv_from", "deriv_to", "infl_from", "all"
# --- END PARAMS ---
import unicodedata
from flexicon import FP_ParameterError
from SIL.LCModel import IMoStemMsa, IMoDerivAffMsa, IMoInflAffMsa

def nfc(text):
    return unicodedata.normalize("NFC", text or "")

# Find the exception feature if adding, via the "Exception Features"
# possibility list (generic wrapper; no per-MSA scanning needed).
chosen_feature = None
chosen_feature_label = None
if ACTION == "add" and FEATURE_NAME:
    ef_list = project.PossibilityLists.FindList("Exception Features")
    if ef_list is None:
        report.Error("'Exception Features' possibility list not found in this project")
    else:
        chosen_feature = project.PossibilityLists.FindItem(ef_list, FEATURE_NAME)
        if chosen_feature:
            chosen_feature_label = project.PossibilityLists.GetItemName(chosen_feature)

if ACTION == "add" and FEATURE_NAME and not chosen_feature:
    report.Error(f"Exception feature '{FEATURE_NAME}' not found in any exception feature list")
else:
    # Determine which senses to process
    target_senses = []
    if SELECTION_MODE == "custom_field":
        cf_field = project.CustomFields.FindField("LexSense", CUSTOM_FIELD)
        if not cf_field:
            report.Error(f"Custom field '{CUSTOM_FIELD}' not found on LexSense")
        else:
            for entry in project.LexEntry.GetAll():
                for sense in project.LexEntry.GetSenses(entry):
                    try:
                        marker = project.CustomFields.GetValue(sense, CUSTOM_FIELD)
                    except FP_ParameterError:
                        continue
                    if marker and str(marker).strip().lower() == "x":
                        target_senses.append(sense)
    else:  # headwords
        wanted = set(nfc(h) for h in HEADWORDS) if HEADWORDS else None
        for entry in project.LexEntry.GetAll():
            if wanted is None or nfc(project.LexEntry.GetHeadword(entry)) in wanted:
                for sense in project.LexEntry.GetSenses(entry):
                    target_senses.append(sense)

    # Process marked senses
    changed = 0
    would_change = 0
    for sense in target_senses:
        entry = project.Senses.GetOwningEntry(sense)
        gloss = project.Senses.GetGloss(sense)
        headword = project.LexEntry.GetHeadword(entry)
        meaning = gloss if gloss else project.Senses.GetDefinition(sense)

        # Find MSA and target field based on morphtype
        for msa in project.MSA.GetAll(entry):
            ex_field = None
            msa_type = None

            if MORPHTYPE in ["stem", "all"]:
                if msa.is_stem_msa:
                    stem = IMoStemMsa(msa.as_stem_msa())  # raw-lcm: exception features not wrapped
                    ex_field = stem.ProdRestrictRC  # raw-lcm: exception features not wrapped
                    msa_type = "stem"

            if MORPHTYPE in ["deriv_from", "all"] and not ex_field:
                if msa.is_deriv_aff_msa:
                    deriv = IMoDerivAffMsa(msa.as_deriv_aff_msa())  # raw-lcm: exception features not wrapped
                    ex_field = deriv.FromProdRestrictRC  # raw-lcm: exception features not wrapped
                    msa_type = "deriv_from"

            if MORPHTYPE in ["deriv_to", "all"] and not ex_field:
                if msa.is_deriv_aff_msa:
                    deriv = IMoDerivAffMsa(msa.as_deriv_aff_msa())  # raw-lcm: exception features not wrapped
                    ex_field = deriv.ToProdRestrictRC  # raw-lcm: exception features not wrapped
                    msa_type = "deriv_to"

            if MORPHTYPE in ["infl_from", "all"] and not ex_field:
                if msa.is_infl_aff_msa:
                    infl = IMoInflAffMsa(msa.as_infl_aff_msa())  # raw-lcm: exception features not wrapped
                    ex_field = infl.FromProdRestrictRC  # raw-lcm: exception features not wrapped
                    msa_type = "infl_from"

            if ex_field and msa_type:
                if ACTION == "clear":
                    if modifyAllowed:
                        try:
                            ex_field.Clear()
                            report.Info(f"cleared exception features from sense '{meaning}' of entry '{headword}' ({msa_type})", project.BuildGotoURL(sense))
                            changed += 1
                        except Exception as e:
                            report.Error(f"error clearing exception features from sense '{meaning}' of entry '{headword}': {e}", project.BuildGotoURL(sense))
                    else:
                        report.Info(f"(dry run) would clear exception features from sense '{meaning}' of entry '{headword}' ({msa_type})", project.BuildGotoURL(sense))
                        would_change += 1
                else:  # add
                    if chosen_feature and chosen_feature not in ex_field:
                        if modifyAllowed:
                            try:
                                ex_field.Add(chosen_feature)
                                report.Info(f"added exception feature '{chosen_feature_label}' to sense '{meaning}' of entry '{headword}' ({msa_type})", project.BuildGotoURL(sense))
                                changed += 1
                            except Exception as e:
                                report.Error(f"error adding exception feature to sense '{meaning}' of entry '{headword}': {e}", project.BuildGotoURL(sense))
                        else:
                            report.Info(f"(dry run) would add exception feature '{chosen_feature_label}' to sense '{meaning}' of entry '{headword}' ({msa_type})", project.BuildGotoURL(sense))
                            would_change += 1

    if modifyAllowed:
        report.Info(f"total changed: {changed}")
    else:
        report.Info(f"total to change: {would_change}")

bulk-set-stem-name.code:
# --- PARAMS ---
SELECTION_MODE = "custom_field"  # "custom_field" or "headwords"
CUSTOM_FIELD = "FTFlags"  # name of the custom field to check for "x" marker (ignored if SELECTION_MODE == "headwords")
HEADWORDS = []  # exact headwords to match (ignored if SELECTION_MODE == "custom_field"); empty list = all marked allomorphs
ACTION = "add"  # "add" or "clear"
STEM_NAME = ""  # name of stem name to add; use "" to just clear (ignored if ACTION == "clear")
LIMIT = 2000  # max allomorphs to process
# --- END PARAMS ---
import unicodedata
from SIL.LCModel import IMoStemAllomorph, IMoStemName

def nfc(text):
    return unicodedata.normalize("NFC", text or "")

def pos_matches_or_is_descendant(candidate_pos, target_pos):
    """Walk up the POS hierarchy from candidate_pos looking for target_pos."""
    p = candidate_pos
    while p is not None:
        if p == target_pos:
            return True
        p = project.POS.GetParent(p)
    return False

# Find the stem name if adding
chosen_stem_name = None
chosen_pos = None
chosen_stem_label = None
if ACTION == "add" and STEM_NAME:
    for pos in project.POS.GetAll():
        pos_name = project.POS.GetName(pos)
        try:
            for raw_stem_name in pos.StemNamesOC:  # raw-lcm: stem names not wrapped (flexicon gap #573)
                stem_name = IMoStemName(raw_stem_name)  # raw-lcm: stem names not wrapped
                sn_name = str(stem_name.Name.AnalysisDefaultWritingSystem.Text) if stem_name.Name else ""  # raw-lcm: stem names not wrapped
                if nfc(sn_name) == nfc(STEM_NAME):
                    chosen_stem_name = stem_name
                    chosen_pos = pos
                    chosen_stem_label = f"{pos_name} - {sn_name}"
                    break
        except Exception:
            pass
        if chosen_stem_name:
            break

if ACTION == "add" and STEM_NAME and not chosen_stem_name:
    report.Error(f"stem name '{STEM_NAME}' not found in any POS")
else:
    # Determine which allomorphs to process
    target_allos = []
    if SELECTION_MODE == "custom_field":
        cf_field = project.CustomFields.FindField("MoForm", CUSTOM_FIELD)
        if not cf_field:
            report.Error(f"custom field '{CUSTOM_FIELD}' not found on allomorphs (MoForm)")
        else:
            for entry in project.LexEntry.GetAll():
                for allo in project.Allomorphs.GetAll(entry):
                    try:
                        marker = project.CustomFields.GetValue(allo, CUSTOM_FIELD)
                        if marker and str(marker).strip().lower() == "x":
                            target_allos.append((entry, allo))
                    except Exception:
                        pass
    else:  # headwords
        wanted = set(nfc(h) for h in HEADWORDS) if HEADWORDS else None
        for entry in project.LexEntry.GetAll():
            if wanted is None or nfc(project.LexEntry.GetHeadword(entry)) in wanted:
                for allo in project.Allomorphs.GetAll(entry):
                    target_allos.append((entry, allo))

    # Process marked allomorphs
    changed = 0
    would_change = 0
    for idx, (entry, allo) in enumerate(target_allos):
        if changed + would_change >= LIMIT:
            report.Warning(f"limit of {LIMIT} reached; process again to continue")
            break

        headword = project.LexEntry.GetHeadword(entry)
        form = project.Allomorphs.GetForm(allo)

        if not allo.is_stem_allomorph:
            report.Warning(f"allomorph '{form}' of entry '{headword}' is not a stem allomorph; skipping", project.BuildGotoURL(allo))
            continue

        # Stem names are a raw LCM field (flexicon gap #573); write via the
        # raw LCM object, not the wrapper (wrapper has no __setattr__, a
        # write to the wrapper attribute would silently be a no-op).
        concrete_allo = IMoStemAllomorph(allo.lcm_object)  # raw-lcm: stem names not wrapped

        if ACTION == "clear":
            try:
                if concrete_allo.StemNameRA:  # raw-lcm: stem names not wrapped
                    if modifyAllowed:
                        concrete_allo.StemNameRA = None  # raw-lcm: stem names not wrapped
                        report.Info(f"cleared stem name from allomorph '{form}' of entry '{headword}'", project.BuildGotoURL(allo))
                        changed += 1
                    else:
                        report.Info(f"(dry run) would clear stem name from allomorph '{form}' of entry '{headword}'", project.BuildGotoURL(allo))
                        would_change += 1
            except Exception as e:
                report.Error(f"error clearing stem name from allomorph '{form}' of entry '{headword}': {e}", project.BuildGotoURL(entry))
        else:  # add
            if chosen_stem_name:
                try:
                    if concrete_allo.StemNameRA is None:  # raw-lcm: stem names not wrapped
                        # Validate POS match: entry's stem-MSA POS must be, or
                        # descend from, the stem name's owning POS.
                        pos_match = False
                        for msa in project.MSA.GetAll(entry):
                            if msa.is_stem_msa and msa.pos_main:
                                if pos_matches_or_is_descendant(msa.pos_main, chosen_pos):
                                    pos_match = True
                                    break

                        if not pos_match:
                            report.Warning(f"POS mismatch for allomorph '{form}' of entry '{headword}'; skipping", project.BuildGotoURL(entry))
                        else:
                            if modifyAllowed:
                                concrete_allo.StemNameRA = chosen_stem_name  # raw-lcm: stem names not wrapped
                                report.Info(f"added stem name '{chosen_stem_label}' to allomorph '{form}' of entry '{headword}'", project.BuildGotoURL(allo))
                                changed += 1
                            else:
                                report.Info(f"(dry run) would add stem name '{chosen_stem_label}' to allomorph '{form}' of entry '{headword}'", project.BuildGotoURL(allo))
                                would_change += 1
                    else:
                        report.Warning(f"stem name already set on allomorph '{form}' of entry '{headword}'; skipping", project.BuildGotoURL(allo))
                except Exception as e:
                    report.Error(f"error processing allomorph '{form}' of entry '{headword}': {e}", project.BuildGotoURL(entry))

    if modifyAllowed:
        report.Info(f"total changed: {changed}")
    else:
        report.Info(f"total to change: {would_change}")

case-duplicate-entries.code:
# --- PARAMS ---
# No tunable parameters; checks all entries and all senses
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


# Map from (lowercase_headword + POS_abbrev) to (entry_id, original_headword, POS_abbrev)
seen_map = {}
duplicates_found = 0

for entry in project.LexEntry.GetAll():
    headword = nfc(project.LexEntry.GetHeadword(entry))
    if not headword:
        continue

    # Check each sense's POS (an entry can have senses with different POSs)
    for sense in project.LexEntry.GetSenses(entry):
        pos = project.Senses.GetPartOfSpeech(sense)
        if not pos:
            continue

        # Get POS abbreviation or name
        pos_str = str(pos)

        # Create composite key: lowercase headword + POS
        key = nfc(headword.lower()) + pos_str

        entry_id = id(entry)

        if key in seen_map:
            prev_id, prev_headword, prev_pos = seen_map[key]
            if prev_id != entry_id:
                report.Warning(
                    f'Case-only duplicate: "{headword}" (POS={pos_str}) duplicates "{prev_headword}" with same POS',
                    project.BuildGotoURL(entry),
                )
                duplicates_found += 1
        else:
            seen_map[key] = (entry_id, headword, pos_str)

report.Info(f"Checked {len(seen_map)} unique (headword, POS) combinations")
report.Info(f"Found {duplicates_found} case-only duplicate entries")

complex-form-components-missing.code:
# --- PARAMS ---
SEPARATOR = " "  # delimiter to split multi-word forms (usually space)
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


# Collect all single-word headwords (normalized)
single_words = set()
multi_word_entries = []

for entry in project.LexEntry.GetAll():
    headword = nfc(project.LexEntry.GetHeadword(entry))
    if not headword:
        continue
    words = headword.split(SEPARATOR)
    if len(words) == 1:
        single_words.add(words[0])
    elif len(words) > 1:
        multi_word_entries.append((headword, entry))

report.Info(f"Found {len(single_words)} single-word lexemes and {len(multi_word_entries)} multi-word lexemes")

# Check each multi-word entry for missing component words
missing_found = 0
for headword, entry in multi_word_entries:
    words = headword.split(SEPARATOR)
    for word in words:
        if word not in single_words:
            report.Warning(
                f'Component word "{word}" in multi-word entry "{headword}" not found in lexicon',
                project.BuildGotoURL(entry),
            )
            missing_found += 1

report.Info(f"Reported {missing_found} missing component words")

complex-forms-and-variants.code:
# --- PARAMS ---
SHOW_COMPLEX_FORMS = True  # report complex form entries and components
SHOW_VARIANTS = True  # report variant entries and their chains
# --- END PARAMS ---

import unicodedata
from SIL.LCModel.Core.KernelInterfaces import ITsString

def nfc(text):
    return unicodedata.normalize("NFC", text or "")

def get_morph_type_name(morph_type):
    """Get morph type name from object (raw LCM access - flexicon gap #583)"""
    if morph_type is None:
        return "unknown"
    try:
        return nfc(ITsString(morph_type.Name.BestAnalysisAlternative).Text)  # flexicon gap: #583 (no morph-type name getter)
    except AttributeError:
        return "unknown"

def resolve_complex_form_component_entry(comp):
    """GetComplexFormComponents legally mixes ILexEntry and ILexSense; its own
    docstring's documented pattern is a ClassName check (# raw-lcm: documented
    discriminator), since neither type exposes an isinstance-friendly
    discriminator on the bare ICmObject."""
    if comp.ClassName == "LexEntry":  # raw-lcm: documented discriminator (GetComplexFormComponents docstring)
        return comp
    if comp.ClassName == "LexSense":  # raw-lcm: documented discriminator (GetComplexFormComponents docstring)
        return project.Senses.GetOwningEntry(comp)
    return None

def get_sense_from_entry_or_chain(entry):
    """Walk variant chain to find entry with senses"""
    visited = set()
    while True:
        # Prevent infinite loops
        entry_id = id(entry)
        if entry_id in visited:
            return entry
        visited.add(entry_id)

        # Get senses
        senses = list(project.LexEntry.GetSenses(entry))
        if senses:
            return entry

        # Check if this is a variant with no senses - get all variants of entry
        variants = project.Variants.GetAll(entry)
        if not variants:
            return entry

        # Get the main entry from variant chain (GetComponentLexemes is
        # documented to always return ILexEntry directly)
        found_next = False
        for var in variants:
            components = project.Variants.GetComponentLexemes(var)
            if components:
                entry = components[0]
                found_next = True
                break

        if not found_next:
            return entry

complex_forms_found = 0
variants_found = 0

if SHOW_COMPLEX_FORMS:
    report.Info("=== Complex Form Entries ===")

    for entry in project.LexEntry.GetAll():
        headword = nfc(project.LexEntry.GetHeadword(entry))

        # Get complex form components for this entry
        components = project.LexEntry.GetComplexFormComponents(entry)

        if components and len(components) >= 2:
            complex_forms_found += 1

            report.Info(
                f"{headword} [Complex Form]",
                project.BuildGotoURL(entry)
            )
            report.Info(f"  Components: {len(components)}")

            for i, comp in enumerate(components):
                comp_entry = resolve_complex_form_component_entry(comp)
                if comp_entry is None:
                    report.Info(f"    [{i+1}] (unrecognized component type)")
                    continue
                comp_headword = project.LexEntry.GetHeadword(comp_entry)
                comp_mt = project.LexEntry.GetMorphType(comp_entry)
                mt_name = get_morph_type_name(comp_mt)

                report.Info(f"    [{i+1}] {comp_headword} ({mt_name})")

if SHOW_VARIANTS:
    report.Info("=== Variant Entries ===")

    for entry in project.LexEntry.GetAll():
        headword = nfc(project.LexEntry.GetHeadword(entry))

        # Check for variants of this entry
        variants = project.Variants.GetAll(entry)

        if variants:
            for var in variants:
                var_type = project.Variants.GetType(var)
                type_name = project.Variants.GetTypeName(var_type) if var_type else "none"

                # Get the main entry (first component in variant chain)
                components = project.Variants.GetComponentLexemes(var)
                main_entry = components[0] if components else None

                # Walk variant chain if main entry has no senses
                if main_entry:
                    main_with_senses = get_sense_from_entry_or_chain(main_entry)
                else:
                    main_with_senses = None

                variants_found += 1

                main_headword = "unknown"
                if main_with_senses:
                    main_headword = project.LexEntry.GetHeadword(main_with_senses)

                report.Info(
                    f"{headword} -> {main_headword} [Variant]",
                    project.BuildGotoURL(entry)
                )
                report.Info(f"  Type: {type_name}")

# Summary
