from SIL.LCModel.Core.KernelInterfaces import TsStrFactory

def _build_paragraph_contents(run_specs):
    """Build one ITsString from (text, ws_tag) pairs."""
    tsf = TsStrFactory()
    bldr = tsf.GetIncBldr()
    for text, ws_tag in run_specs:
        ws = project.WSHandle(ws_tag)
        bldr.AppendTsString(tsf.MakeString(text, ws))
    return bldr.GetString()

# Vernacular + gloss-style runs in one paragraph (reference / paradigm text).
