# --- PARAMS ---
TITLE_PATTERN = r"^zzRecipeTest"  # Regex pattern to match text titles; default is safe, matches texts starting with "zzRecipeTest"; use ".*" with caution as it deletes ALL texts
INCLUDE_SCRIPTURE = False  # If True, also delete Scripture book data if any exists
# --- END PARAMS ---
import re
import unicodedata

vern_ws = project.GetDefaultVernacularWSHandle()

texts_to_delete = []

# Collect all texts matching the pattern
for text in project.Texts.GetAll():
    # Get titles in both writing systems
    vern_title = project.Texts.GetTitle(text, wsHandle=vern_ws) or ""
    analysis_title = project.Texts.GetTitle(text) or ""  # defaults to analysis WS

    # Normalize for consistent matching
    vern_normalized = unicodedata.normalize("NFC", vern_title)
    analysis_normalized = unicodedata.normalize("NFC", analysis_title)

    # Check if title matches pattern
    matches = (re.search(TITLE_PATTERN, vern_normalized) or
               re.search(TITLE_PATTERN, analysis_normalized))

    if matches:
        texts_to_delete.append({
            "text": text,
            "vern": vern_normalized,
            "analysis": analysis_normalized
        })

# Report what was found
if not texts_to_delete:
    report.Info(f"No texts matched pattern '{TITLE_PATTERN}'")
else:
    report.Info(f"Found {len(texts_to_delete)} text(s) matching pattern '{TITLE_PATTERN}':")

    # List the titles that will be deleted
    for item in texts_to_delete:
        title_display = f"{item['vern']}" if item['vern'] else f"(unnamed)"
        if item['analysis'] and item['analysis'] != item['vern']:
            title_display += f"|{item['analysis']}"
        report.Info(f"  {title_display}")

    # Perform deletion if allowed
    if modifyAllowed:
        deleted_count = 0
        error_count = 0
        for item in texts_to_delete:
            try:
                project.Texts.Delete(item["text"])
                deleted_count += 1
                title = item['vern'] or "(unnamed)"
                report.Info(f"Deleted text '{title}'")
            except Exception as e:
                error_count += 1
                title = item['vern'] or "(unnamed)"
                report.Error(
                    f"Failed to delete text '{title}': {e}",
                    project.BuildGotoURL(item["text"])
                )

        report.Info(f"SUMMARY: {deleted_count} deleted, {error_count} error(s)")
    else:
        report.Info(f"(dry run) would delete {len(texts_to_delete)} text(s)")
        report.Warning("This operation is destructive. Verify the pattern matches expected texts before running with write enabled.")

# Handle optional scripture cleanup
if INCLUDE_SCRIPTURE:
    try:
        books = list(project.ScrBooks.GetAll())
        if books:
            if modifyAllowed:
                deleted_books = 0
                for book in books:
                    try:
                        project.ScrBooks.Delete(book)
                        deleted_books += 1
                    except Exception as e:
                        report.Error(f"Failed to delete Scripture book: {e}")
                report.Info(f"Deleted {deleted_books} Scripture book(s)")
            else:
                report.Info(f"(dry run) would delete {len(books)} Scripture book(s)")
        else:
            report.Info("No Scripture data found to delete")
    except Exception as e:
        report.Warning(f"Could not access Scripture data: {e}")

ensure-morpheme-entries.code:
# --- PARAMS ---
MORPHEMES = [
    # (form with affix markers, gloss, POS name or None)
    ("zzRecipeTestku-", "zzINF", None),
    ("zzRecipeTestsoma", "zzread", None),
]
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


def split_markers(raw):
    """Return (bare form, morph type name) from a marked form."""
    form = nfc(raw).strip()
    if form.startswith("-") and form.endswith("-") and len(form) > 2:
        return form[1:-1], "infix"
    if form.endswith("-"):
        return form[:-1], "prefix"
    if form.startswith("-"):
        return form[1:], "suffix"
    if form.startswith("="):
        return form[1:], "enclitic"
    if form.endswith("="):
        return form[:-1], "proclitic"
    return form, "stem"


# Morph type name, object and stem-ness, keyed by lowercase name and by GUID.
mt_by_name = {}
mt_name_by_guid = {}
for name, mt, is_stem in project.LexEntry.GetAvailableMorphTypes():
    mt_by_name[name.lower()] = (name, is_stem)
    mt_name_by_guid[str(mt.Guid)] = name

rows = []
ok = True
for raw, gloss, pos_name in MORPHEMES:
    form, mt_name = split_markers(raw)
    if not form:
        report.Error(f"{raw!r}: empty form after removing markers")
        ok = False
        continue
    if mt_name not in mt_by_name:
        report.Error(f"{raw!r}: morph type {mt_name!r} not in this project")
        ok = False
        continue
    pos = None
    if pos_name:
        pos = project.POS.Find(pos_name)
        if pos is None:
            report.Error(f"{raw!r}: unknown POS {pos_name!r}")
            ok = False
            continue
    rows.append((raw, form, mt_by_name[mt_name], gloss, pos))

if not ok:
    report.Error("validation failed: fix PARAMS before any write")
else:
    # (lexeme form, morph type name) -> entries, for the existence check.
    by_form = {}
    for entry in project.LexEntry.GetAll():
        mt = project.LexEntry.GetMorphType(entry)
        mt_name = mt_name_by_guid.get(str(mt.Guid), "?") if mt is not None else "?"
        lf = nfc(project.LexEntry.GetLexemeForm(entry))
        by_form.setdefault(lf, []).append((mt_name, entry))

    created = skipped = 0
    for raw, form, (mt_name, is_stem), gloss, pos in rows:
        same_form = by_form.get(form, [])
        same_type = [e for n, e in same_form if n.lower() == mt_name.lower()]
        if same_type:
            glosses = [project.Senses.GetGloss(s) for e in same_type for s in project.LexEntry.GetSenses(e)]
            report.Info(f"exists {raw}: {len(same_type)} entr{'y' if len(same_type) == 1 else 'ies'}, glosses={glosses}")
            skipped += 1
            continue
        others = sorted(set(n for n, _e in same_form))
        if others:
            report.Warning(f"{raw}: form exists only as {others}; creating a {mt_name}")
        if not modifyAllowed:
            report.Info(f"(dry run) would create {raw} as {mt_name} gloss={gloss!r} POS={project.POS.GetName(pos) if pos else None}")
            continue
        if modifyAllowed:
            entry = project.LexEntry.Create(form, mt_name, create_blank_sense=False)
            sense = project.LexEntry.AddSense(entry, gloss)
            if is_stem:
                project.MSA.CreateStem(sense, pos)
            else:
                project.MSA.CreateUnclassifiedAffix(sense, pos)
            by_form.setdefault(form, []).append((mt_name, entry))
            created += 1
            report.Info(f"created {project.LexEntry.GetHeadword(entry)} as {mt_name} gloss={gloss!r} guid={project.LexEntry.GetGuid(entry)}")
    report.Info(f"done: {created} created, {skipped} already present, {len(rows) - created - skipped} not created")

