# --- PARAMS ---
MODE = "approved"  # "approved" | "disapproved" | "all" | "parser-failed"
WORDFORMS = []  # empty list = all wordforms; provide specific wordforms to limit
# --- END PARAMS ---
import unicodedata
from flexicon import ApprovalStatusTypes

# Validate MODE
valid_modes = {"approved", "disapproved", "all", "parser-failed"}
if MODE not in valid_modes:
    report.Error(f"MODE must be one of {valid_modes}, got {MODE!r}")
else:
    def norm(text):
        return unicodedata.normalize("NFC", text or "").casefold()

    # Build set of wordforms to process (empty = all)
    target_wordforms = set(norm(w) for w in WORDFORMS) if WORDFORMS else None

    # First pass: collect analyses whose human evaluation should be cleared
    to_remove = []
    for wf in project.Wordforms.GetAll():
        form = project.Wordforms.GetForm(wf)
        if target_wordforms is not None and norm(form) not in target_wordforms:
            continue

        for analysis in project.Wordforms.GetAnalyses(wf):
            human_eval = project.WfiAnalyses.GetHumanEvaluation(analysis)
            if human_eval is None:
                continue  # No human evaluation on this analysis

            approves = bool(human_eval.Approves)
            is_computer_approved = project.WfiAnalyses.IsComputerApproved(analysis)

            should_remove = False
            remove_reason = ""

            if MODE == "approved":
                if approves:
                    should_remove = True
                    remove_reason = "human-approved"
            elif MODE == "disapproved":
                if not approves:
                    should_remove = True
                    remove_reason = "human-disapproved"
            elif MODE == "all":
                should_remove = True
                remove_reason = "human-evaluated"
            elif MODE == "parser-failed":
                if not is_computer_approved:
                    should_remove = True
                    remove_reason = "human evaluation on parser-failed analysis"

            if should_remove:
                to_remove.append((wf, form, analysis, remove_reason))

    # Second pass: clear collected human evaluations
    removed_count = 0
    for wf, form, analysis, reason in to_remove:
        if modifyAllowed:
            try:
                project.WfiAnalyses.SetApprovalStatus(analysis, ApprovalStatusTypes.UNAPPROVED)
                removed_count += 1
                report.Info(
                    f"removed {reason} for {form}",
                    project.BuildGotoURL(wf)
                )
            except Exception as e:
                report.Error(f"failed to remove evaluation for {form}: {e}")
        else:
            report.Info(f"(dry run) would remove {reason} for {form}")

    if not modifyAllowed:
        report.Warning("Run with write_enabled=True to actually remove evaluations")

    report.Info(f"Total evaluations processed: {len(to_remove)}")
    if modifyAllowed and removed_count > 0:
        report.Warning(f"Removed {removed_count} evaluations. Make sure to leave the Word Analyses area!")

reorder-affix-templates.code:
# --- PARAMS ---
POS_NAME = "Verb"
# --- END PARAMS ---

import re
import unicodedata
from SIL.LCModel import IPartOfSpeech


def nfc(s):
    return unicodedata.normalize("NFC", s or "")


def starts_with_number(s):
    return bool(re.match(r'^\d+', s))


# Validate and find POS
matches = [p for p in project.POS.GetAll() if nfc(project.POS.GetName(p)) == nfc(POS_NAME)]

if len(matches) != 1:
    if matches:
        report.Error(f"POS '{POS_NAME}' matches {len(matches)} entries; must match exactly 1")
    else:
        avail = sorted(project.POS.GetName(p) for p in project.POS.GetAll())
        report.Error(f"POS '{POS_NAME}' not found. Available: {avail[:5]}")
else:
    pos = matches[0]
    pos_name = project.POS.GetName(pos)
    templates = list(project.MorphRules.GetAllAffixTemplatesForPOS(pos))

    if len(templates) <= 1:
        report.Info(f"{pos_name} has {len(templates)} template(s); nothing to sort.")
    else:
        names = [t.name for t in templates]
        all_numeric = all(starts_with_number(n) for n in names)

        if all_numeric:
            report.Info(f"Sorting {pos_name} templates numerically.")
            sorted_templates = sorted(templates, key=lambda t: int(re.match(r'^\d+', t.name).group()))
        else:
            report.Info(f"Sorting {pos_name} templates alphabetically.")
            sorted_templates = sorted(templates, key=lambda t: t.name)

        report.Info(f"Current order:")
        for t in templates:
            report.Info(f"  {t.name}")

        report.Info(f"New order:")
        for t in sorted_templates:
            report.Info(f"  {t.name}")

        if modifyAllowed:
            try:
                coll = IPartOfSpeech(pos).AffixTemplatesOS  # raw-lcm: flexicon gap #580 (direct access to collection)
                for new_idx, target in enumerate(sorted_templates):
                    for cur_idx, t in enumerate(coll):
                        if t.Guid == target.concrete.Guid:
                            if cur_idx != new_idx:
                                coll.MoveTo(cur_idx, cur_idx, coll, new_idx)  # raw-lcm: flexicon gap #580 (MoveTo not wrapped)
                            break
                report.Info(f"Sorted {pos_name} templates.")
            except Exception as e:
                report.Error(f"Error sorting {pos_name} templates: {e}")
        else:
            report.Info("(dry run) Run with modifyAllowed=True to apply sort.")

