# --- PARAMS ---
HEADWORD = "ma-2"  # exact headword of the entry owning the allomorph (errors cleanly if 0 or more than 1 entry matches)
FORM = "lf"  # "lf" = the lexeme form, or the exact form of one alternate allomorph
REMOVE = []  # existing environment strings to remove (exact notation, e.g. "/ _ [V]"); nothing is created
ADD = []  # existing environment strings to add (exact notation, e.g. "/ _ e"); nothing is created
# --- END PARAMS ---
import unicodedata


def nfc(text):
    return unicodedata.normalize("NFC", text or "")


def env_names(allo):
    return sorted(nfc(project.Environments.GetStringRepresentation(e)) for e in project.Allomorphs.GetPhoneEnv(allo))


# Resolve the entry by exact headword (NFC both sides); refuse on 0 or >1.
matches = [e for e in project.LexEntry.GetAll() if nfc(project.LexEntry.GetHeadword(e)) == nfc(HEADWORD)]
if len(matches) != 1:
    report.Error(f"{HEADWORD}: found {len(matches)} entries, need exactly 1; nothing changed")
else:
    entry = matches[0]
    allos = list(project.Allomorphs.GetAll(entry))  # includes the lexeme form, listed first
    if FORM == "lf":
        target = allos[0] if allos else None
    else:
        target = next((a for a in allos if nfc(project.Allomorphs.GetForm(a)) == nfc(FORM)), None)
    if target is None:
        report.Error(f"{HEADWORD} / allomorph {FORM} not found; nothing changed")
    else:
        envs = {nfc(project.Environments.GetStringRepresentation(e)).strip(): e for e in project.Environments.GetAll()}
        missing = [x for x in REMOVE + ADD if nfc(x).strip() not in envs]
        if missing:
            report.Error(f"environments not found: {missing}; nothing changed")
        else:
            report.Info(f"{HEADWORD} {FORM} BEFORE env={env_names(target)}", project.BuildGotoURL(entry))
            if modifyAllowed:
                for x in REMOVE:
                    project.Allomorphs.RemovePhoneEnv(target, envs[nfc(x).strip()])
                for x in ADD:
                    project.Allomorphs.AddPhoneEnv(target, envs[nfc(x).strip()])
            else:
                report.Info(f"(dry run) would remove {REMOVE} and add {ADD}")
            report.Info(f"{HEADWORD} {FORM} AFTER env={env_names(target)}", project.BuildGotoURL(entry))

text-analysis-gaps.code:
# --- PARAMS ---
TEXT_TITLE = ""  # exact text title to check; "" means all texts
SKIP_CAPITALIZED_NONINITIAL = True  # skip capitalized non-sentence-initial words (likely proper nouns)
# --- END PARAMS ---

import unicodedata
from SIL.LCModel import ICmObject

def nfc(text):
    return unicodedata.normalize("NFC", text or "")

def resolve_wordform_and_analysis(token):
    """Resolve a segment occurrence token to (wordform, analysis-or-None).
    Returns (None, None) for punctuation tokens."""
    cls = token.ClassName  # raw-lcm: dispatch on occurrence token subtype (documented SegmentOperations.GetAnalyses contract)
    if cls == "PunctuationForm":
        return None, None
    if cls == "WfiWordform":
        return token, None
    if cls == "WfiGloss":
        analysis = ICmObject(token).Owner  # raw-lcm: flexicon gap #575 (WfiGloss -> owning WfiAnalysis)
    else:  # "WfiAnalysis"
        analysis = token
    wf = project.WfiAnalyses.GetOwningWordform(analysis)
    return wf, analysis

# Collect all text titles if filtering
target_texts = {}
if TEXT_TITLE:
    wanted = nfc(TEXT_TITLE)
    for text in project.Texts.GetAll():
        if nfc(project.Texts.GetTitle(text)) == wanted:
            target_texts[text] = wanted
            break
else:
    for text in project.Texts.GetAll():
        target_texts[text] = nfc(project.Texts.GetTitle(text))

if not target_texts:
    if TEXT_TITLE:
        report.Error(f"no text with title {TEXT_TITLE}")
    else:
        report.Info("no texts in project")
else:
    unanalyzed_count = 0
    incomplete_bundle_count = 0

    for text in target_texts.keys():
        text_title = target_texts[text]
        report.Info(f"Checking text: {text_title}")

        for paragraph in project.Paragraphs.GetAll(text):
            for segment in project.Segments.GetAll(paragraph):
                for token in project.Segments.GetAnalyses(segment):
                    wf, analysis = resolve_wordform_and_analysis(token)
                    if wf is None:
                        continue  # punctuation

                    wf_form = nfc(project.Wordforms.GetForm(wf))

                    # Skip empty forms and SFM markers
                    if not wf_form or wf_form.startswith("\\"):
                        continue

                    # Skip capitalized non-sentence-initial words if requested
                    if SKIP_CAPITALIZED_NONINITIAL and wf_form[0].isupper():
                        continue

                    if analysis is None:
                        unanalyzed_count += 1
                        report.Warning(
                            f"No analysis found for word: {wf_form}",
                            project.BuildGotoURL(wf)
                        )
                        continue

                    for bundle in project.WfiAnalyses.GetMorphBundles(analysis):
                        sense = project.WfiMorphBundles.GetSense(bundle)
                        msa = project.WfiMorphBundles.GetMSA(bundle)
                        morph = project.WfiMorphBundles.GetMorph(bundle)

                        if morph and (not sense or not msa):
                            incomplete_bundle_count += 1
                            morph_form = project.Allomorphs.GetForm(morph) if morph else "?"
                            report.Warning(
                                f"Incomplete morpheme bundle in word '{wf_form}': "
                                f"morph='{morph_form}' sense={'MISSING' if not sense else 'OK'} "
                                f"msa={'MISSING' if not msa else 'OK'}",
                                project.BuildGotoURL(wf)
                            )

    # Summary
    report.Info(f"Unanalyzed words found: {unanalyzed_count}")
    report.Info(f"Incomplete morpheme bundles found: {incomplete_bundle_count}")
    report.Info("Analysis complete")

